window.kbPageData["views/entry/k-243780be74415e1a"] = {"key":"entry/k-243780be74415e1a","state":{"route":"entry/k-243780be74415e1a"},"node":{"id":"k-243780be74415e1a","mode":"k","title":"公历二月的天数","type":"制度与规则","domain":"数学","reading":"","intro":"","priority":100,"aliases":["公历平年二月有28天，闰年二月有29天"],"qs":["国考 2025 行政执法 行测#71"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"公历平年的二月有28天，闰年的二月有29天。","review":{"definition":"公历平年的二月有28天，闰年的二月有29天。","explanation":"连续28天正好是4周，小张每周跑4次，合计16次。二月跑了17次，说明当年是闰年，且2月29日也跑了。三月后28天跑16次，所以3月1日至3日每天都跑。2月29日至3月3日连跑4天，只能对应周一至周四。3月31日距3月3日正好4周，也是周四，因此4月1日为周五。四月的前28天跑16次，余下两天是周五和周六，合计16次，选A。","references":[],"evidence":"故该年2月应为29天，最后1天（2月29日）再夜跑1次","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2025 行政执法 行测#71":{"paper":"国考 2025 行政执法 行测","n":71,"mod":"数量关系","src":["d8efe4e19862104d89c8.pdf",12],"asrc":["e2c4b1970d2b49eac0fd.pdf",23],"card":"253761c06c0588ad55c9c802","links":[{"id":"k-243780be74415e1a","role":"解题依据","why":"整四周的次数与二月实际次数相差一次，由此确定二月有一个余日。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-243780be74415e1a":[["国考 2025 行政执法 行测#71"]]}};
